# -*- coding: utf-8 -*-"""l2d_segment_selfcheck.py — motion3.json 段格式的**自证 + 实检**（只读，不写任何产物）。背景（为什么需要它）：`extract_motions.py` 把 Unity AnimationClip 的曲线写成 Cubismmotion3.json 的 `Segments` 扁平数组。这个数组的语义只有一份权威定义 —— **运行时的解析器**。本工具把那套求值器 1:1 移植过来（源：vendored`pixi-live2d-display@0.4.0/dist/cubism4.min.js`，sha256 af1267e6…，与`gallery_src/vendor/MANIFEST.json` 逐字节相同），于是判据不再依赖"我们自己的代码看起来对"：  · parse 布局：`[type,...]` 的消费步长（线性 3 / 贝塞尔 7）、`points` 累加（1 / 3）、    首点与上一段共享（`basePointIndex = a-1`）—— 对不上就撑爆按 TotalSegmentCount 预分配的数组  · 求值器选择：`evaluate = Meta.AreBeziersRestricted ? Z : J`      J（非 restricted）：用控制点的**绝对时间**解三次方程（Cardano）取参数      Z（restricted）：参数 = 归一化时间，de Casteljau 只取各点的**值**  · **Z/J 一致**：我们恒把控制点 x 放在 t0+dt/3、t0+2dt/3（均匀）⇒ 两条路径必须数值一致。    若哪天又写成"归一化分数"，这条会立刻红（那正是历史上"肢体猛窜"的写法）。  · **值域有界**：段内采样值必须落在该段两端关键帧值域内（+小容差）。归一化分数那种写法    会让控制点值跑到 0.6/0.8 而目标值在几十 ⇒ 采样值飞出值域，**这条就是"猛窜"的机械判据**。  · 关键帧对齐：每段的终点 (time,value) 必须等于 Unity 原始关键帧（曲线不能自说自话）。用法:  py -3 scripts/diag/l2d_segment_selfcheck.py --selftest      # 内置夹具自证：好数据必须全绿、**故意写坏的数据必须被抓**（阴性对照，无资产也能跑）  py -3 scripts/diag/l2d_segment_selfcheck.py --dir Output/Live2D/aersasi_2  py -3 scripts/diag/l2d_segment_selfcheck.py --all          # 全库扫描（Output/Live2D）  py -3 scripts/diag/l2d_segment_selfcheck.py --dir X --json退出码: 0 = 全绿; 1 = 有违规; 2 = 环境/参数错误"""import argparseimport jsonimport mathimport osimport sysHERE = os.path.dirname(os.path.abspath(__file__))S = os.path.dirname(HERE)ROOT = os.path.dirname(S)sys.path.insert(0, S)sys.stdout.reconfigure(encoding='utf-8', errors='replace')import paths as P  # noqa: E402# ---------------------------------------------------------------- 运行时求值器（1:1 移植）LINEAR, BEZIER, STEPPED, INVSTEPPED = 0, 1, 2, 3def _lerp(a, b, t):    """q(a,b,t)：两点的 (time,value) 线性插值。"""    return (a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)def ev_linear(pts, t):    """$：归一化参数 + 线性（运行时对 Linear 段的求值器）。"""    p0, p1 = pts[0], pts[1]    d = (p1[0] - p0[0])    i = (t - p0[0]) / d if d else 0.0    if i < 0:        i = 0.0    return p0[1] + (p1[1] - p0[1]) * idef ev_Z(pts, t):    """Z：AreBeziersRestricted 路径 —— 参数取归一化时间，de Casteljau 只用各点的**值**。"""    p0, p1, p2, p3 = pts[0], pts[1], pts[2], pts[3]    d = (p3[0] - p0[0])    i = (t - p0[0]) / d if d else 0.0    if i < 0:        i = 0.0    a, b, c = _lerp(p0, p1, i), _lerp(p1, p2, i), _lerp(p2, p3, i)    d1, d2 = _lerp(a, b, i), _lerp(b, c, i)    return _lerp(d1, d2, i)[1]def _cardano(a, b, c, d):    """运行时用的三次方程求解（a t³ + b t² + c t + d = 0，取 [0,1] 内的实根）。"""    if abs(a) < 1e-12:        if abs(b) < 1e-12:            return (-d / c) if abs(c) > 1e-12 else 0.0        disc = c * c - 4 * b * d        if disc < 0:            return 0.0        r = math.sqrt(disc)        cands = [(-c + r) / (2 * b), (-c - r) / (2 * b)]        return next((x for x in cands if -1e-6 <= x <= 1 + 1e-6), cands[0])    p = (3 * a * c - b * b) / (3 * a * a)    q = (2 * b ** 3 - 9 * a * b * c + 27 * a * a * d) / (27 * a ** 3)    disc = (q / 2) ** 2 + (p / 3) ** 3    if disc >= 0:        s = math.sqrt(disc)        u = math.copysign(abs(-q / 2 + s) ** (1 / 3), -q / 2 + s)        v = math.copysign(abs(-q / 2 - s) ** (1 / 3), -q / 2 - s)        return u + v - b / (3 * a)    r = math.sqrt(-(p / 3) ** 3)    phi = math.acos(max(-1.0, min(1.0, -q / (2 * r))))    return 2 * math.sqrt(-p / 3) * math.cos(phi / 3) - b / (3 * a)def ev_J(pts, t):    """J：非 restricted 路径 —— 用控制点的**绝对时间**解三次方程取参数，再 de Casteljau。"""    p0, p1, p2, p3 = pts[0], pts[1], pts[2], pts[3]    s, r, a, o = p0[0], p3[0], p1[0], p2[0]    n = r - 3 * o + 3 * a - s    l = 3 * o - 6 * a + 3 * s    h = 3 * a - 3 * s    u = s - t    d = _cardano(n, l, h, u)    c, m, p_ = _lerp(p0, p1, d), _lerp(p1, p2, d), _lerp(p2, p3, d)    e, f = _lerp(c, m, d), _lerp(m, p_, d)    return _lerp(e, f, d)[1]# ---------------------------------------------------------------- 运行时 parse（1:1 移植）def parse_motion(m):    """按运行时 `CubismMotion.parse()` 的方式把 Curves[].Segments 摊成 segments/points。    返回 (segments, points, curves_meta, restricted)。    每段记 base 点下标 / 类型；每曲线记 baseSegmentIndex 与 segmentCount，用来复现    `evaluateCurve()` 的查找逻辑。    """    meta = m.get('Meta') or {}    restricted = bool(meta.get('AreBeziersRestricted'))    segments, points, cmeta = [], [], []    o = a = 0    for ci, c in enumerate(m.get('Curves') or []):        segs = c.get('Segments') or []        base_seg = o        l = 0        while l < len(segs):            if l == 0:                segments.append({'base': a, 'type': None, 'ci': ci})                points.append((float(segs[l]), float(segs[l + 1])))                a += 1                l += 2            else:                segments.append({'base': a - 1, 'type': None, 'ci': ci})   # 与上一段共享起点            typ = segs[l]            if typ == BEZIER:                segments[-1]['type'] = BEZIER                for k in (1, 3, 5):                    points.append((float(segs[l + k]), float(segs[l + k + 1])))                a += 3                l += 7            elif typ in (LINEAR, STEPPED, INVSTEPPED):                segments[-1]['type'] = typ                points.append((float(segs[l + 1]), float(segs[l + 2])))                a += 1                l += 3            else:                raise ValueError(f'段类型非法 {typ!r}（curve#{ci}）')            o += 1        cmeta.append({'baseSegmentIndex': base_seg, 'segmentCount': o - base_seg,                      'id': c.get('Id'), 'target': c.get('Target')})    return segments, points, cmeta, restrictedRESTRICTED_MODE = [False]        # check_motion 设置；evaluate_curve 读它（对应运行时字段）def evaluate_curve(segments, points, cm, t):    """复现运行时 `evaluateCurve(model, curveIndex, time)`（含"末段之后取末值"）。"""    last = points[0][1]    for l in range(cm['baseSegmentIndex'], cm['baseSegmentIndex'] + cm['segmentCount']):        sg = segments[l]        consume = 3 if sg['type'] == BEZIER else 1        o = sg['base'] + consume        last = points[o][1]        if points[o][0] > t:            pts = points[sg['base']:sg['base'] + consume + 1]            if sg['type'] == BEZIER:                return (ev_Z if RESTRICTED_MODE[0] else ev_J)(pts, t)            if sg['type'] == LINEAR:                return ev_linear(pts, t)            if sg['type'] == STEPPED:                return pts[0][1]            return pts[1][1]    return lastdef curve_keys(segments, points, cm):    """该曲线的关键帧序列 [(time,value), …]（首点 + 每段终点）。"""    ks = [points[segments[cm['baseSegmentIndex']]['base']]]    for l in range(cm['baseSegmentIndex'], cm['baseSegmentIndex'] + cm['segmentCount']):        sg = segments[l]        ks.append(points[sg['base'] + (3 if sg['type'] == BEZIER else 1)])    return ksdef check_motion(m, samples=8, zj_tol=1e-3):    """一条 motion3.json 的全部判据。返回违规清单（空 = 通过）。"""    meta = m.get('Meta') or {}    v = []    try:        segments, points, cmeta, restricted = parse_motion(m)    except Exception as e:        return [f'parse 失败: {type(e).__name__}: {e}']    RESTRICTED_MODE[0] = restricted    if len(segments) != meta.get('TotalSegmentCount'):        v.append(f'TotalSegmentCount 不符：实际 {len(segments)} vs Meta {meta.get("TotalSegmentCount")}'                 '（运行时按 Meta 预分配数组，对不上会报 basePointIndex undefined）')    if len(points) != meta.get('TotalPointCount'):        v.append(f'TotalPointCount 不符：实际 {len(points)} vs Meta {meta.get("TotalPointCount")}')    for cm in cmeta:        ks = curve_keys(segments, points, cm)        if not ks:            continue        for k in range(1, len(ks)):            if ks[k][0] < ks[k - 1][0] - 1e-6:                v.append(f'{cm["id"]}: 关键帧时间非单调 @{k}')                break        lo = min(x[1] for x in ks)        hi = max(x[1] for x in ks)        span = max(hi - lo, 1e-6)        tol = 1e-3 + 0.02 * span        for l in range(cm['baseSegmentIndex'], cm['baseSegmentIndex'] + cm['segmentCount']):            sg = segments[l]            consume = 3 if sg['type'] == BEZIER else 1            t0, t1 = points[sg['base']][0], points[sg['base'] + consume][0]            if t1 <= t0:                v.append(f'{cm["id"]}: 段 [{t0},{t1}] 时间轴非递增')                continue            for k in range(1, samples + 1):                t = t0 + (t1 - t0) * k / samples                val = evaluate_curve(segments, points, cm, t)                if val < lo - tol or val > hi + tol:                    v.append(f'{cm["id"]}: **值域过冲** t={t:.3f} 值={val:.3f} 越界 '                             f'[{lo:.3f},{hi:.3f}]（"肢体猛窜"的机械判据）')                    break            if sg['type'] == BEZIER:                pts = points[sg['base']:sg['base'] + 4]                # 结构性判据：控制点的时间坐标必须落在本段时间区间内。                #   （"归一化分数"写法在 t0>1/3 的段上必然越界 —— 那些段很常见，因为                #     曲线中段的每段 t0 都大于 0.333。这条与下面的 Z/J 判据互补。）                for k in (1, 2):                    if not (t0 - 1e-6 <= pts[k][0] <= t1 + 1e-6):                        v.append(f'{cm["id"]}: 贝塞尔控制点{k} 的时间 {pts[k][0]:.4g} '                                 f'不在段区间 [{t0:.4g},{t1:.4g}]（疑似写成归一化分数）')                        break                worst = 0.0                for k in range(1, samples + 1):                    t = t0 + (t1 - t0) * k / samples                    worst = max(worst, abs(ev_Z(pts, t) - ev_J(pts, t)))                if worst > zj_tol * max(1.0, span):                    v.append(f'{cm["id"]}: Z/J 两路径不一致 max|Z-J|={worst:.4g}'                             '（控制点不是"绝对坐标 + 均匀 x"，两条运行时路径会给出不同动作）')    return v# ---------------------------------------------------------------- 夹具（阴性对照）def _bez(t0, v0, out0, t1, v1, in1):    """按 extract_motions.py 的规则写一段贝塞尔（绝对控制点、x 均匀落在 1/3、2/3）。"""    dt = t1 - t0    return [1, t0 + dt / 3.0, v0 + out0 * dt / 3.0,            t1 - dt / 3.0, v1 - in1 * dt / 3.0, t1, v1]def _lin(t1, v1):    return [0, t1, v1]def _motion(curves, restricted=True, duration=2.5):    """按运行时的计数规则算 Meta（与生成端同一套契约）。"""    seg = pts = 0    for c in curves:        s = c['Segments']        l = 0        while l < len(s):            if l == 0:                pts += 1                l += 2            typ = s[l]            if typ == BEZIER:                l += 7                pts += 3            else:                l += 3                pts += 1            seg += 1    return {'Version': 3,            'Meta': {'Duration': duration, 'Fps': 30.0, 'Loop': True,                     'AreBeziersRestricted': restricted, 'CurveCount': len(curves),                     'TotalSegmentCount': seg, 'TotalPointCount': pts,                     'UserDataCount': 0, 'TotalUserDataSize': 0},            'Curves': curves, 'UserData': [], 'Physics': None}def fixture_good():    """正确写法：绝对控制点 + 均匀 x（应全绿）。"""    return _motion([        {'Target': 'Parameter', 'Id': 'ParamAngleX',         'Segments': [0.0, 0.0] + _bez(0.0, 0.0, 0.0, 1.2, 10.0, 0.0) + _bez(1.2, 10.0, 0.0, 2.5, 4.0, 0.0)},        {'Target': 'Parameter', 'Id': 'ParamBodyAngleZ',         'Segments': [0.0, 5.0] + _lin(2.5, 5.0)},        {'Target': 'PartOpacity', 'Id': 'Part01',         'Segments': [0.0, 1.0] + _lin(2.5, 1.0)},    ])def fixture_bad_normalized_restricted():    """历史坏写法 A：控制点写成**归一化分数**，且 Meta.AreBeziersRestricted=true。    运行时走 Z（参数=归一化时间、只用各点的值）⇒ 曲线形状塌到 0.6~0.8；    而 J 走绝对时间解方程 ⇒ 完全另一个数 ⇒ 判据「Z/J 不一致」必须抓到。    """    return _motion([        {'Target': 'Parameter', 'Id': 'ParamArmL',         'Segments': [0.0, 0.0, 1, 0.333, 0.6, 0.667, 0.8, 2.5, 30.0]},    ])def fixture_bad_normalized_absolute():    """历史坏写法 B：同上但 Meta.AreBeziersRestricted 缺省/false ⇒ 走 J。    控制点被当成「t=0.333 秒、值=0.6」⇒ 段内解出段外参数 ⇒ 值飞出关键帧值域    ⇒ 判据「值域过冲」必须抓到（这就是"肢体猛窜"的机械判据）。    """    return _motion([        {'Target': 'Parameter', 'Id': 'ParamArmL',         'Segments': [0.0, 0.0, 1, 0.333, 0.6, 0.667, 0.8, 2.5, 30.0]},    ], restricted=False)def fixture_bad_normalized_midseg():    """坏写法 C：**中段**的归一化控制点（t0=1.0 > 0.333）⇒ 结构性判据必须抓到。    为什么要单独一条：曲线首段从 t0=0 起时，x=0.333 恰好落在区间内，结构性判据抓不到它，    只能靠 Z/J 判据。而中段的每段 t0 都大于 0.333，是**大多数**段的形态。    """    return _motion([        {'Target': 'Parameter', 'Id': 'ParamArmR',         'Segments': [1.0, 5.0] + _bez(1.0, 5.0, 0.0, 1.8, 20.0, 0.0)                     + [1, 0.333, 0.6, 0.667, 0.8, 2.5, 35.0]},    ])def fixture_bad_layout():    """段序/长度写错（贝塞尔少一个终点）⇒ 计数与 Meta 对不上，必须被抓。"""    m = fixture_good()    c = m['Curves'][0]    c['Segments'] = c['Segments'][:-1]          # 砍掉最后一段的终点值    return mdef selftest():    cases = [('good（正确写法）', fixture_good(), 0),             ('bad:归一化分数+restricted', fixture_bad_normalized_restricted(), 1),             ('bad:归一化分数+非restricted', fixture_bad_normalized_absolute(), 1),             ('bad:归一化分数+中段(t0>1/3)', fixture_bad_normalized_midseg(), 1),             ('bad:段长/段序错', fixture_bad_layout(), 1)]    ok = True    print('=== 夹具自证（判据必须能区分"好数据"与"历史上的坏数据"）===')    for name, m, want in cases:        v = check_motion(m)        hit = 1 if v else 0        flag = 'OK ' if hit == want else 'XX '        print(f'  {flag}{name}: 违规 {len(v)} 条（期望{"有" if want else "无"}）')        for x in v[:3]:            print(f'      · {x}')        ok = ok and hit == want    print('[PASS] 判据有区分度' if ok else '[FAIL] 判据没有区分度（别信它的绿灯）')    return 0 if ok else 1# ---------------------------------------------------------------- 实检def check_dir(d):    files = []    if os.path.isdir(os.path.join(d, 'motion')):        d = os.path.join(d, 'motion')    for base, _dd, ff in os.walk(d):        files += [os.path.join(base, f) for f in ff if f.endswith('.motion3.json')]    bad, n, nseg = [], 0, 0    for f in sorted(files):        try:            m = json.load(open(f, encoding='utf-8'))        except Exception as e:            bad.append((f, [f'JSON 读取失败 {type(e).__name__}: {e}']))            continue        n += 1        nseg += len(m.get('Meta', {}).get('TotalSegmentCount') and                   (m.get('Curves') or []))        v = check_motion(m)        if v:            bad.append((f, v))    print(f'扫描 {d}: {n} 个 motion3.json，违规 {len(bad)} 个')    for f, v in bad[:20]:        print(f'  XX {os.path.relpath(f, ROOT)}')        for x in v[:3]:            print(f'       · {x}')    return bad, ndef main():    ap = argparse.ArgumentParser(description='motion3.json 段格式自证 + 实检')    ap.add_argument('--selftest', action='store_true', help='只跑内置夹具（无资产也能跑）')    ap.add_argument('--dir', help='扫某个模型目录（含 motion/ 子目录）')    ap.add_argument('--all', action='store_true', help='扫 Output/Live2D 全库')    ap.add_argument('--json', action='store_true')    a = ap.parse_args()    if a.selftest or not (a.dir or a.all):        return selftest()    targets = [P.LIVE2D_OUT] if a.all else [a.dir]    allbad = {}    for t in targets:        if not os.path.isdir(t):            print(f'XX 目录不存在: {t}')            return 2        bad, n = check_dir(t)        allbad[t] = {f: v for f, v in bad}    if a.json:        print(json.dumps({k: {os.path.relpath(f, ROOT): v for f, v in d.items()}                          for k, d in allbad.items()}, ensure_ascii=False, indent=1))    nbad = sum(len(d) for d in allbad.values())    print(f'结论: {"OK 全部通过" if not nbad else f"XX {nbad} 个文件有违规"}')    return 1 if nbad else 0if __name__ == '__main__':    sys.exit(main())